/** Wall-clock time for call timers (only ever read in handlers and effects). */
const clock = () => Date.now();

/** 0714228 -> "071 4228", 10 digits -> "071 422 8890"; short ones as they are. */
function formatNumber(n: string) {
  if (n.length <= 4) return n;
  if (n.length <= 7) return `${n.slice(0, 3)} ${n.slice(3)}`;
  return `${n.slice(0, 3)} ${n.slice(3, 6)} ${n.slice(6)}`;
}

/** The coiled cord as a looping curve from the handset down to the body; `lift` follows the handset. */
function cordPath(lift: number) {
  const P = [
    [112, 230 + lift],
    [24, 290 + lift * 0.6],
    [18, 560],
    [112, 632],
  ];
  const N = 360;
  const loops = 30;
  const amp = 8;
  let d = "";
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const mt = 1 - t;
    const bx =
      mt ** 3 * P[0][0] +
      3 * mt * mt * t * P[1][0] +
      3 * mt * t * t * P[2][0] +
      t ** 3 * P[3][0];
    const by =
      mt ** 3 * P[0][1] +
      3 * mt * mt * t * P[1][1] +
      3 * mt * t * t * P[2][1] +
      t ** 3 * P[3][1];
    const dx =
      3 * mt * mt * (P[1][0] - P[0][0]) +
      6 * mt * t * (P[2][0] - P[1][0]) +
      3 * t * t * (P[3][0] - P[2][0]);
    const dy =
      3 * mt * mt * (P[1][1] - P[0][1]) +
      6 * mt * t * (P[2][1] - P[1][1]) +
      3 * t * t * (P[3][1] - P[2][1]);
    const len = Math.hypot(dx, dy) || 1;
    const [tx, ty, nx, ny] = [dx / len, dy / len, -dy / len, dx / len];
    const phi = t * loops * Math.PI * 2;
    // a trochoid: sideways swing plus a little back-and-forth along the cord, so it reads as loops
    const x = bx + nx * Math.sin(phi) * amp + tx * Math.cos(phi) * amp * 0.55;
    const y = by + ny * Math.sin(phi) * amp + ty * Math.cos(phi) * amp * 0.55;
    d += `${i ? "L" : "M"}${x.toFixed(1)} ${y.toFixed(1)}`;
  }
  return d;
}

/* ---------------------------------------------------------------------------
 * Sound: tiny WebAudio synth, created on the first touch
 * ------------------------------------------------------------------------- */

let audio: AudioContext | null = null;
const ac = () => (audio ??= new AudioContext());

function tone(
  freq: number,
  dur: number,
  o: { type?: OscillatorType; gain?: number; at?: number; to?: number } = {},
) {
  const c = ac();
  const t = c.currentTime + (o.at ?? 0);
  const osc = c.createOscillator();
  const g = c.createGain();
  osc.type = o.type ?? "sine";
  osc.frequency.setValueAtTime(freq, t);
  if (o.to) osc.frequency.exponentialRampToValueAtTime(o.to, t + dur);
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(o.gain ?? 0.15, t + 0.004);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  osc.connect(g).connect(c.destination);
  osc.start(t);
  osc.stop(t + dur + 0.02);
}

function noise(
  dur: number,
  o: {
    at?: number;
    gain?: number;
    freq?: number;
    type?: BiquadFilterType;
  } = {},
) {
  const c = ac();
  const t = c.currentTime + (o.at ?? 0);
  const buf = c.createBuffer(1, Math.ceil(c.sampleRate * dur), c.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  const src = c.createBufferSource();
  src.buffer = buf;
  const f = c.createBiquadFilter();
  f.type = o.type ?? "lowpass";
  f.frequency.value = o.freq ?? 800;
  const g = c.createGain();
  g.gain.setValueAtTime(o.gain ?? 0.3, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  src.connect(f).connect(g).connect(c.destination);
  src.start(t);
}

/** A struck piece of metal: a few inharmonic partials, higher ones dying faster, plus a click. */
function metal(
  base: number,
  o: { at?: number; gain?: number; decay?: number } = {},
) {
  const gain = o.gain ?? 0.08;
  const decay = o.decay ?? 0.3;
  [1, 1.47, 2.09, 2.76].forEach((r, i) =>
    tone(base * r * (1 + (Math.random() - 0.5) * 0.01), decay / (1 + i * 0.6), {
      gain: gain / (1 + i * 0.9),
      at: o.at,
    }),
  );
  noise(0.01, { at: o.at, freq: 5000, type: "highpass", gain: gain * 1.5 });
}

/**
 * Telephone line tones: two sine waves mixed, switched on and off in a cadence.
 * Returns a stop so a tone can be cut short (hang up, first digit dialed).
 */
function lineTone(
  freqs: number[],
  dur: number,
  cadence?: [on: number, off: number],
) {
  const c = ac();
  const t = c.currentTime;
  const out = c.createGain();
  out.gain.value = 0;
  if (cadence) {
    for (let at = 0; at < dur; at += cadence[0] + cadence[1]) {
      out.gain.setValueAtTime(0.05, t + at);
      out.gain.setValueAtTime(0, t + Math.min(dur, at + cadence[0]));
    }
  } else {
    out.gain.setValueAtTime(0.05, t);
    out.gain.setValueAtTime(0, t + dur);
  }
  out.connect(c.destination);
  const oscs = freqs.map((f) => {
    const o = c.createOscillator();
    o.frequency.value = f;
    o.connect(out);
    o.start(t);
    o.stop(t + dur + 0.05);
    return o;
  });
  return () => {
    const n = c.currentTime;
    out.gain.cancelScheduledValues(n);
    out.gain.setValueAtTime(0, n);
    oscs.forEach((o) => o.stop(n + 0.02));
  };
}

const sfx = {
  unlock: () => void ac().resume(),
  /** One pulse of the governor as the dial spins home. */
  tick: (vol = 1) => {
    noise(0.007, {
      freq: 3000 + Math.random() * 600,
      type: "bandpass",
      gain: 0.55 * vol,
    });
    tone(1900, 0.018, { gain: 0.025 * vol });
  },
  /** Finger hits the stop. */
  stop: () => {
    noise(0.04, { freq: 520, gain: 0.5 });
    tone(170, 0.07, { gain: 0.12, to: 110 });
  },
  /** A digit lands in the plate. */
  clack: () => {
    noise(0.02, { freq: 2200, type: "bandpass", gain: 0.35 });
    tone(760, 0.04, { gain: 0.04 });
  },
  /** Two bursts of a real bell: the clapper strikes fast between two gongs. */
  ring: () => {
    for (const start of [0, 1.1])
      for (let i = 0; i < 18; i++)
        metal(i % 2 ? 1210 : 1150, {
          at: start + i * 0.042,
          gain: 0.045,
          decay: 0.7,
        });
  },
  /** One incoming ring. */
  bell: () => {
    for (let i = 0; i < 22; i++)
      metal(i % 2 ? 1210 : 1150, { at: i * 0.042, gain: 0.04, decay: 0.6 });
  },
  dialTone: (dur: number) => lineTone([350, 440], dur),
  ringBack: (dur: number) => lineTone([440, 480], dur, [1.4, 1.6]),
  pickup: () => {
    noise(0.03, { freq: 900, type: "bandpass", gain: 0.5 });
    metal(1400, { gain: 0.025, decay: 0.12 });
  },
  /** A sheepish little two-note bell. */
  oops: () => {
    metal(1150, { gain: 0.05, decay: 0.5 });
    metal(860, { at: 0.22, gain: 0.05, decay: 0.7 });
  },
  /** Handset rattling on the cradle, and a dull tap of the bell. */
  rattle: () => {
    for (let i = 0; i < 7; i++) {
      noise(0.03, {
        at: i * 0.075,
        freq: 1300 + Math.random() * 400,
        type: "bandpass",
        gain: 0.7,
      });
      tone(210, 0.05, { at: i * 0.075, gain: 0.05, to: 150 });
    }
    metal(620, { at: 0.04, gain: 0.05, decay: 0.3 });
  },
  hangup: () => {
    noise(0.05, { freq: 600, gain: 0.6 });
    metal(900, { gain: 0.03, decay: 0.2 });
  },
};

