              </span>
            </dd>
          </div>
        ))}
      </dl>
      <p className="mt-5 text-[13px] text-muted-foreground">
        Try dialing <span className="font-medium text-foreground">0714</span>{" "}
        for Grandma.
      </p>
    </RotaryPasscode>
  );
}
